CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS bikes (id INTEGER PRIMARY KEY AUTOINCREMENT, category_id INTEGER NOT NULL, number TEXT NOT NULL, name TEXT NOT NULL, owner TEXT, info TEXT, photo TEXT, photo_mime TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_bikes_cat ON bikes(category_id);
CREATE TABLE IF NOT EXISTS voters (id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT NOT NULL UNIQUE, name TEXT NOT NULL, email TEXT, community TEXT, motor TEXT, city TEXT, consent_mkt INTEGER NOT NULL DEFAULT 0, ip TEXT, ua TEXT, void INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_voters_ip ON voters(ip);
CREATE TABLE IF NOT EXISTS votes (id INTEGER PRIMARY KEY AUTOINCREMENT, voter_id INTEGER NOT NULL, category_id INTEGER NOT NULL, bike_id INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(voter_id, category_id));
CREATE INDEX IF NOT EXISTS ix_votes_bike ON votes(bike_id);
CREATE TABLE IF NOT EXISTS rate_hits (k TEXT NOT NULL, t INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ix_rate ON rate_hits(k, t);
